import{z as n,x as o,o as A,c as d,q as r,j as i,D as E,d as e,s,S as B,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"RAG 评测 RAGAS","description":"","frontmatter":{"title":"RAG 评测 RAGAS","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-evaluation.md","filePath":"llm/rag-evaluation.md","lastUpdated":1791413859000}'),p={name:"llm/rag-evaluation.md"};function m(D,a,R,h,u,c){const t=o("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="rag-评测-ragas" tabindex="-1">RAG 评测 RAGAS <a class="header-anchor" href="#rag-评测-ragas" aria-label="Permalink to &quot;RAG 评测 RAGAS&quot;">​</a></h1><div class="epigraph"><p>端到端准确率把检索错误与阅读错误绑死。要把上下文相关性、忠实度、答案相关性分列，管道才能知道该改哪一段。</p><footer>—— Es 等 RAGAS；检索与生成必须分指标</footer></div><p><a href="/llm/citation-attribution">上一课</a>定义了支撑。工程上还要一套可回归的自动分，不必每夜都上人评。Es 等人的 RAGAS 把 RAG 拆成若干 LLM 辅助指标。缺口是读懂这些分测的是管道哪一段。后课自适应 RAG 默认：你已经能测「该不该检索」，而不是只看最终 BLEU。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只有最终答案对错时，检索召回低与阅读器胡编可以分数相同。RAGAS 一类协议提出：忠实度（答案是否可由上下文推出）、答案相关性（是否在问所问）、上下文精度/召回（检索块相对需要的证据）。许多实现用 LLM 法官估这些量，于是继承<a href="/llm/llm-judge-bias">裁判偏差</a>：未校准前只能当烟雾。</p><p><span class="marginnote">术语翻译：忠实度就是检查「答案的每个论断能不能从给检索器的资料里读出来」——资料里没有的数字、结论一律算不忠。它管的是「不许编」，不管「答得全不全」；答得全不全归答案相关性管，找没找到资料归检索指标管。</span></p><p>金标可用时，检索用标准 IR 指标（nDCG、Recall@\\(k\\)），生成用支撑与精确匹配。无金标时，RAGAS 是代理，必须抽检。</p><p><span class="marginnote">「上下文召回」需要「该题应引用哪些块」的概念。没有题级证据标注时，这个量是法官的想象，方差大。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小表：检索 Recall@\\(k\\) / nDCG（有金标块时）；忠实度；答案正确（有金标答时）；引用可解析率。RAGAS 分数与表并排，不替代。固定法官模型与提示版本。切片：无检索命中、有命中仍不忠、过检索（块对但答偏）。差异集派人看。</p><p><span class="marginnote">数字实例：Recall@5 = 0.6 意味着每 10 个问题里有 4 个连证据块都没捞进窗口——这 40% 的错答案怎么换阅读器都救不回来。先把检索从 0.6 提到 0.9，再谈调提示，改错的顺序比改的力度更重要。</span></p>',11)),(A(),i(B,null,{default:E(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIPE%5B%22RAG%20%E7%AE%A1%E9%81%93%22%5D%20--%3E%20IR%5B%22%E6%A3%80%E7%B4%A2%20IR%20%E6%8C%87%E6%A0%87%22%5D%0A%20%20PIPE%20--%3E%20FAI%5B%22%E5%BF%A0%E5%AE%9E%E5%BA%A6%22%5D%0A%20%20PIPE%20--%3E%20ANS%5B%22%E7%AD%94%E6%A1%88%E6%AD%A3%E7%A1%AE%20%2F%20%E7%9B%B8%E5%85%B3%22%5D%0A%20%20IR%20--%3E%20DIAG%5B%22%E5%AE%9A%E4%BD%8D%E6%95%85%E9%9A%9C%E6%AE%B5%22%5D%0A%20%20FAI%20--%3E%20DIAG%0A%20%20ANS%20--%3E%20DIAG%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"分列指标对应管道的条件依赖：检索差则阅读器无论多忠也会信息不足；检索好而忠实度低是阅读器或提示问题；二者都高而答案不相关是任务理解问题。把它们加总成单分会回到 MMLU 式平均。自适应课将用这些信号决定是否检索、是否再检索。",-1)),(A(),i(B,null,{default:E(()=>[s(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALL%5B%22%E4%B8%80%E6%89%B9%E8%AF%84%E6%B5%8B%E7%BB%93%E6%9E%9C%22%5D%20--%3E%20Q1%7B%22%E6%A3%80%E7%B4%A2%E6%8C%87%E6%A0%87%E5%A4%9F%E9%AB%98%E5%90%97%22%7D%0A%20%20Q1%20--%20%22%E5%90%A6%22%20--%3E%20FIX1%5B%22%E5%85%88%E4%BF%AE%E6%A3%80%E7%B4%A2%3A%20%E5%88%87%E5%88%86%20%2F%20%E5%B5%8C%E5%85%A5%20%2F%20%E6%B7%B7%E5%90%88%22%5D%0A%20%20Q1%20--%20%22%E6%98%AF%22%20--%3E%20Q2%7B%22%E5%BF%A0%E5%AE%9E%E5%BA%A6%E9%AB%98%E5%90%97%22%7D%0A%20%20Q2%20--%20%22%E5%90%A6%22%20--%3E%20FIX2%5B%22%E4%BF%AE%E9%98%85%E8%AF%BB%E5%99%A8%3A%20%E6%8F%90%E7%A4%BA%20%2F%20%E4%B8%8A%E4%B8%8B%E6%96%87%E5%8E%8B%E7%BC%A9%20%2F%20%E6%8D%A2%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20Q2%20--%20%22%E6%98%AF%22%20--%3E%20Q3%7B%22%E7%AD%94%E6%A1%88%E7%9B%B8%E5%85%B3%E6%80%A7%E9%AB%98%E5%90%97%22%7D%0A%20%20Q3%20--%20%22%E5%90%A6%22%20--%3E%20FIX3%5B%22%E4%BF%AE%E4%BB%BB%E5%8A%A1%E7%90%86%E8%A7%A3%3A%20%E9%97%AE%E9%A2%98%E6%94%B9%E5%86%99%20%2F%20%E8%B7%AF%E7%94%B1%22%5D%0A%20%20Q3%20--%20%22%E6%98%AF%22%20--%3E%20GOOD%5B%22%E7%AE%A1%E9%81%93%E5%81%A5%E5%BA%B7%2C%20%E7%9C%8B%E5%89%A9%E4%BD%99%E9%95%BF%E5%B0%BE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">常见误区：初学者容易把「忠实度 0.9」读成「系统 90% 可靠」。它只是法官模型对单条答案可推出性的估计，法官自己也会看走眼；同一个提示换一个法官模型，分数能差一截。所以未校准的分数只能用来发现大坑，发布决策仍要靠抽检人评。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>自动忠实度不是法律保证。下一课自适应 RAG：用信号在「直答 / 检索 / 再检索」之间路由。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RAG 必须分列检索与忠实度，禁止只报端到端。</li><li>RAGAS 等 LLM 指标是代理，要校准与抽检。</li><li>有金标块时优先标准 IR 指标。</li><li>出处：Es 等 RAGAS；ALCE；IR 评测通识。</li></ul>',5))])}const F=n(p,[["render",m]]);export{_ as __pageData,F as default};
